export const getGetFraudDashboardUrl = () => {




  return `/api/fraud-sahayak/dashboard`
}

/**
 * @summary Get case and agent activity summary
 */
export const getFraudDashboard = async ( options?: Parameters<typeof customFetch>[1]): Promise<DashboardSummary> => {

  return customFetch<DashboardSummary>(getGetFraudDashboardUrl(),
  {
    ...options,
    method: 'GET'


  }
);}





export const getGetFraudDashboardQueryKey = () => {
    return [
    `/api/fraud-sahayak/dashboard`
    ] as const;
    }


export const getGetFraudDashboardQueryOptions = <TData = Awaited<ReturnType<typeof getFraudDashboard>>, TError = ErrorType<unknown>>( options?: { query?:UseQueryOptions<Awaited<ReturnType<typeof getFraudDashboard>>, TError, TData>, request?: SecondParameter<typeof customFetch>}
) => {

const {query: queryOptions, request: requestOptions} = options ?? {};

  const queryKey =  queryOptions?.queryKey ?? getGetFraudDashboardQueryKey();



    const queryFn: QueryFunction<Awaited<ReturnType<typeof getFraudDashboard>>> = ({ signal }) => getFraudDashboard({ signal, ...requestOptions });





   return  { queryKey, queryFn, ...queryOptions} as UseQueryOptions<Awaited<ReturnType<typeof getFraudDashboard>>, TError, TData> & { queryKey: QueryKey }
}

export type GetFraudDashboardQueryResult = NonNullable<Awaited<ReturnType<typeof getFraudDashboard>>>
export type GetFraudDashboardQueryError = ErrorType<unknown>


/**
 * @summary Get case and agent activity summary
 */

export function useGetFraudDashboard<TData = Awaited<ReturnType<typeof getFraudDashboard>>, TError = ErrorType<unknown>>(
  options?: { query?:UseQueryOptions<Awaited<ReturnType<typeof getFraudDashboard>>, TError, TData>, request?: SecondParameter<typeof customFetch>}

 ):  UseQueryResult<TData, TError> & { queryKey: QueryKey } {

  const queryOptions = getGetFraudDashboardQueryOptions(options)

  const query = useQuery(queryOptions) as  UseQueryResult<TData, TError> & { queryKey: QueryKey };

  return withQueryKey(query, queryOptions.queryKey);
}







